"""Root Langfuse trace for one Copilot v2 turn.

Copilot v2 runs on pydantic-ai, whose ``Instrumentation`` capability emits
OpenTelemetry GenAI spans for the agent run, each model request, and each tool
call. Langfuse's span processor exports every span on the tracer provider, so
those spans need no adapter — they only need a parent. This module supplies it:
one span named ``copilot_v2`` that owns the turn and carries the trace-level
identity and payload attributes, the same set the removed v1 endpoint trace
carried.

The span is opened by the web layer around the whole SSE drain loop rather than
inside the streaming generator. That placement is deliberate: when a client
disconnects mid-stream the ``async for`` unwinds without closing the generator
(Python leaves that to GC), so a context manager inside the generator would
leak the span on the most common failure mode. In the caller, ``__exit__`` runs
on every path.

Tool spans, token counts, and per-request cost all come from pydantic-ai's own
instrumentation. Nothing here writes them.
"""

from __future__ import annotations

import sys
from collections.abc import Iterator
from contextlib import contextmanager
from typing import TYPE_CHECKING, Any

import structlog

from rasa.builder.telemetry.langfuse_integration.constants import (
    COPILOT_V2_TRACE_NAME,
    COPILOT_V2_TRANSPORT_TAG,
    ERROR_TAG,
)
from rasa.builder.telemetry.langfuse_integration.langfuse_compat import with_langfuse
from rasa.builder.telemetry.langfuse_integration.shared import create_session_id

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.types import RunRequest

structlogger = structlog.get_logger()

# AG-UI event types folded into the trace output. Local rather than in
# ``constants``: that module holds the Langfuse vocabulary this code *writes*,
# whereas these are the AG-UI protocol's own names, which it only reads. Kept
# as literals rather than imported from ``ag_ui_events`` (which exposes
# constructors, not names); the drift guard is a test that builds every event
# through those constructors.
_TEXT_MESSAGE_CONTENT = "TEXT_MESSAGE_CONTENT"
_RUN_ERROR = "RUN_ERROR"
_CUSTOM = "CUSTOM"

# CUSTOM event names the v2 runtime emits that carry trace-worthy outcome.
_MESSAGE_METADATA = "message_metadata"
_PLAN_UPDATE = "plan_update"
_COMMIT_INFO = "commit_info"


class CopilotV2TurnTrace:
    """Accumulates one Copilot v2 turn's outcome and writes it to Langfuse.

    A single instance spans one request. The web layer creates it, opens
    :meth:`observe` around the SSE drain loop, and feeds every AG-UI event
    through :meth:`record_event` as it streams. On exit the accumulated
    outcome is written to the trace and the span closes.

    Every Langfuse interaction is best-effort: a telemetry failure is logged at
    debug and swallowed, because a turn must never fail because tracing did.
    """

    def __init__(
        self,
        run_request: "RunRequest",
        user_id: str,
        project_id: str | None,
    ) -> None:
        """Initialize the trace for one turn.

        Args:
            run_request: The parsed AG-UI run request being served.
            user_id: The ``X-User-Id`` header value. Empty when the header was
                absent, which v2 permits unless guardrails blocking is on.
            project_id: The Hello Rasa project id, or ``None`` when unset in
                the environment.
        """
        self._request = run_request
        self._user_id = user_id.strip()
        self._project_id = project_id
        self._text_parts: list[str] = []
        self._response_category: str | None = None
        self._plan: dict[str, Any] | None = None
        self._commit_sha: str | None = None
        self._error: dict[str, str] | None = None

    @contextmanager
    def observe(self) -> Iterator["CopilotV2TurnTrace"]:
        """Open the root span for the turn, closing it on every exit path.

        Yields itself so the caller can pass the same instance to the stream.
        When langfuse is not installed, or opening the span fails, the block
        still runs untraced — the caller sees no difference.
        """
        with with_langfuse() as langfuse_module:
            if langfuse_module is None:
                yield self
                return
            try:
                client = langfuse_module.get_client()
                # ``start_as_current_span`` is a generator-based context
                # manager, so calling it runs none of its body: creating the
                # OTel span and serialising ``input`` both happen in
                # ``__enter__``. Entering and exiting explicitly is what puts
                # those steps under a guard — a ``with`` block here would
                # leave the only half that can fail outside the ``try``.
                span = client.start_as_current_span(
                    name=COPILOT_V2_TRACE_NAME,
                    input=self._trace_input(),
                )
                span.__enter__()
            except Exception as exc:
                self._log_failure("open_span", exc)
                yield self
                return

            try:
                yield self
            except Exception as exc:
                # The route emits RUN_ERROR for anything it catches, so an
                # exception reaching here escaped that handler. Record it
                # so the trace is still tagged, then let it propagate.
                self._record_exception(exc)
                raise
            finally:
                # Runs while the span is still current, which is what
                # ``update_current_trace`` and ``update_current_span``
                # resolve against.
                self._write_outcome(client)
                try:
                    # ``sys.exc_info()`` is whatever is propagating out (a
                    # triple of ``None`` on a clean exit), so the span records
                    # the failure exactly as ``with`` would — including
                    # ``CancelledError``, which the handler above lets past.
                    span.__exit__(*sys.exc_info())
                except Exception as exc:
                    self._log_failure("close_span", exc)

    def record_event(self, event: dict[str, Any]) -> None:
        """Fold one AG-UI event into the turn's accumulated outcome.

        Called once per streamed event, so it does no Langfuse I/O and retains
        no per-delta objects: text deltas are appended to a single list joined
        at close, and the plan keeps only its latest snapshot. Tool-call events
        are ignored outright — pydantic-ai's own tool spans already carry them
        in more detail than an AG-UI event could.

        Args:
            event: One AG-UI event, as emitted by the v2 runtime.
        """
        try:
            event_type = event.get("type")
            if event_type == _TEXT_MESSAGE_CONTENT:
                self._text_parts.append(str(event.get("delta", "")))
            elif event_type == _RUN_ERROR:
                self._error = {
                    "message": str(event.get("message", "")),
                    "error_code": str(event.get("code") or "UnknownError"),
                }
            elif event_type == _CUSTOM:
                self._record_custom_event(
                    str(event.get("name", "")), event.get("value")
                )
        except Exception as exc:
            self._log_failure("record_event", exc)

    def _record_custom_event(self, name: str, value: Any) -> None:
        """Fold a CUSTOM event's payload into the outcome.

        Only the three CUSTOM events the runtime itself emits are read. Host
        vocabulary (a pre-flight's ``policy_violation``) is not: a refused run
        never reaches the agent loop and is short-circuited before the span
        opens.
        """
        if not isinstance(value, dict):
            return
        if name == _MESSAGE_METADATA:
            category = value.get("response_category")
            if category is not None:
                self._response_category = str(category)
        elif name == _PLAN_UPDATE:
            self._plan = value
        elif name == _COMMIT_INFO:
            commit_sha = value.get("commitSha")
            if commit_sha is not None:
                self._commit_sha = str(commit_sha)

    def _record_exception(self, exc: Exception) -> None:
        """Record an escaping exception as the turn's error, if none is set.

        A RUN_ERROR event already seen wins: it is what the user was actually
        shown.
        """
        if self._error is None:
            self._error = {"message": str(exc), "error_code": type(exc).__name__}

    def _write_outcome(self, client: Any) -> None:
        """Write the accumulated outcome to the trace and the root span."""
        try:
            client.update_current_trace(
                user_id=self._user_id or None,
                session_id=self._session_id(),
                input=self._trace_input(),
                output=self._trace_output(),
                metadata=self._trace_metadata(),
                tags=self._trace_tags(),
            )
        except Exception as exc:
            self._log_failure("write_outcome", exc)

        if self._error is None:
            return

        # Guarded separately: the payload above is the likelier of the two to
        # fail (``_plan`` is an arbitrary dict lifted off a client-supplied
        # CUSTOM event), and a failed turn losing its ERROR marking too would
        # cost exactly the traces worth finding.
        try:
            client.update_current_span(
                level="ERROR",
                status_message=self._error["error_code"],
            )
        except Exception as exc:
            self._log_failure("mark_error", exc)

    def _session_id(self) -> str:
        """Build the Langfuse session id, matching v1's composite exactly.

        v1 keys sessions on ``(project, user, chat)``; v2's ``thread_id`` is
        the same concept as v1's ``chat_id``, so reusing the composite groups a
        user's v1 and v2 turns into one Langfuse session. ``str()`` rather than
        a fallback keeps the id byte-identical to v1's when the project id is
        unset — v1 renders the missing value the same way.
        """
        return create_session_id(
            hello_rasa_project_id=str(self._project_id),
            user_id=self._user_id,
            chat_id=self._request.thread_id,
        )

    def _trace_input(self) -> dict[str, Any]:
        """Build the trace input: the user's turn plus its attachments.

        The user text comes from the shared trailing-user predicate, so what
        the trace shows is exactly what the thread store persisted. That module
        hard-imports pydantic-ai, so the import is local: this package is
        otherwise installable without the ``copilot-v2`` extra, and a telemetry
        module must not be the thing that breaks that.
        """
        from rasa.builder.copilot.pydantic_ai.persisted_messages import (
            trailing_user_text,
        )

        return {
            "message": trailing_user_text(self._request.messages),
            "tracker_event_attachments": [
                attachment.model_dump() for attachment in self._request.attachments
            ],
        }

    def _trace_output(self) -> dict[str, Any]:
        """Build the trace output from the accumulated stream."""
        output: dict[str, Any] = {
            "answer": "".join(self._text_parts),
            "response_category": self._response_category,
        }
        if self._plan is not None:
            output["plan"] = self._plan
        if self._commit_sha is not None:
            output["commit_sha"] = self._commit_sha
        if self._error is not None:
            output["error"] = self._error
        return output

    def _trace_metadata(self) -> dict[str, Any]:
        """Build the trace metadata: ids and the run's model configuration."""
        thinking = self._request.thinking
        return {
            "ids": {
                "user_id": self._user_id or None,
                "project_id": self._project_id,
                "thread_id": self._request.thread_id,
                "run_id": self._request.run_id,
                "inspector_session_id": self._request.session_id,
            },
            "model": self._request.model,
            "thinking": {
                "enabled": thinking.enabled,
                "budget": thinking.budget,
                "effort": thinking.effort.value,
            },
        }

    def _trace_tags(self) -> list[str]:
        """Build the trace tags: transport, response category, error state."""
        tags = [COPILOT_V2_TRANSPORT_TAG]
        if self._response_category is not None:
            tags.append(self._response_category)
        if self._error is not None:
            tags.append(ERROR_TAG)
        return tags

    def _log_failure(self, step: str, exc: Exception) -> None:
        """Log a swallowed telemetry failure without the turn's content."""
        structlogger.debug(
            f"copilot_v2_langfuse_telemetry.{step}.failed",
            thread_id=self._request.thread_id,
            error_type=type(exc).__name__,
        )
